//! Embed enumerations and bitfields.

use std::fmt;

/// The type of an embed.
///
/// Most user-created embeds are [`EmbedType::Rich`]. The other variants are
/// generated by Discord for linked images, videos and articles.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub enum EmbedType {
    /// A generic embed rendered with the full set of fields.
    #[default]
    Rich,
    /// An embed containing only an image.
    Image,
    /// An embed containing only a video.
    Video,
    /// An embed containing an animated image.
    Gifv,
    /// An embed containing an article.
    Article,
    /// An embed containing a link preview.
    Link,
}

impl EmbedType {
    /// Returns the lowercase name used by the API.
    #[must_use]
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::Rich => "rich",
            Self::Image => "image",
            Self::Video => "video",
            Self::Gifv => "gifv",
            Self::Article => "article",
            Self::Link => "link",
        }
    }

    /// Converts an API name, returning `None` for unknown values.
    #[must_use]
    pub fn from_name(value: &str) -> Option<Self> {
        match value {
            "rich" => Some(Self::Rich),
            "image" => Some(Self::Image),
            "video" => Some(Self::Video),
            "gifv" => Some(Self::Gifv),
            "article" => Some(Self::Article),
            "link" => Some(Self::Link),
            _ => None,
        }
    }
}

impl fmt::Display for EmbedType {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(self.as_str())
    }
}

/// Wraps the Discord embed flag bitfield.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Hash)]
pub struct EmbedFlags(u64);

impl EmbedFlags {
    /// No flags.
    pub const NONE: Self = Self(0);

    /// The embed was flagged as sensitive content.
    pub const CONTAINS_EXPLICIT_MEDIA: Self = Self(1 << 4);
    /// The embed is a reply to an activity card and is no longer displayed.
    pub const CONTENT_INVENTORY_ENTRY: Self = Self(1 << 5);

    /// Every known embed flag.
    pub const ALL: Self = Self(Self::CONTAINS_EXPLICIT_MEDIA.0 | Self::CONTENT_INVENTORY_ENTRY.0);

    /// Creates an empty flag set.
    #[must_use]
    pub const fn none() -> Self {
        Self::NONE
    }

    /// Creates a set with every known flag enabled.
    #[must_use]
    pub const fn all() -> Self {
        Self::ALL
    }

    /// Returns the raw bitfield.
    #[must_use]
    pub const fn bits(self) -> u64 {
        self.0
    }

    /// Wraps a raw bitfield without validating it.
    #[must_use]
    pub const fn from_bits(bits: u64) -> Self {
        Self(bits)
    }

    /// Wraps a raw bitfield, dropping bits not defined by this crate.
    #[must_use]
    pub const fn from_bits_truncate(bits: u64) -> Self {
        Self(bits & Self::ALL.0)
    }

    /// Returns `true` if no flag is set.
    #[must_use]
    pub const fn is_empty(self) -> bool {
        self.0 == 0
    }

    /// Returns `true` if all flags in `other` are enabled in `self`.
    #[must_use]
    pub const fn contains(self, other: Self) -> bool {
        (self.0 & other.0) == other.0
    }

    /// Returns `true` if at least one flag in `other` is enabled in `self`.
    #[must_use]
    pub const fn intersects(self, other: Self) -> bool {
        (self.0 & other.0) != 0
    }

    /// Enables the flags in `other`.
    pub fn insert(&mut self, other: Self) {
        self.0 |= other.0;
    }

    /// Disables the flags in `other`.
    pub fn remove(&mut self, other: Self) {
        self.0 &= !other.0;
    }

    /// Toggles the flags in `other`.
    pub fn toggle(&mut self, other: Self) {
        self.0 ^= other.0;
    }

    /// Enables or disables the flags in `other`.
    pub fn set(&mut self, other: Self, value: bool) {
        if value {
            self.insert(other);
        } else {
            self.remove(other);
        }
    }

    /// Returns the union of both sets.
    #[must_use]
    pub const fn union(self, other: Self) -> Self {
        Self(self.0 | other.0)
    }

    /// Returns the intersection of both sets.
    #[must_use]
    pub const fn intersection(self, other: Self) -> Self {
        Self(self.0 & other.0)
    }

    /// Returns the flags in `self` that are not in `other`.
    #[must_use]
    pub const fn difference(self, other: Self) -> Self {
        Self(self.0 & !other.0)
    }

    /// Returns the flags enabled in exactly one of the two sets.
    #[must_use]
    pub const fn symmetric_difference(self, other: Self) -> Self {
        Self(self.0 ^ other.0)
    }

    /// Returns every known flag that is not enabled in `self`.
    #[must_use]
    pub const fn complement(self) -> Self {
        Self(!self.0 & Self::ALL.0)
    }

    /// Returns whether the embed contains explicit media.
    #[must_use]
    pub const fn contains_explicit_media(self) -> bool {
        self.contains(Self::CONTAINS_EXPLICIT_MEDIA)
    }

    /// Returns whether the embed is a reply to an activity card.
    #[must_use]
    pub const fn content_inventory_entry(self) -> bool {
        self.contains(Self::CONTENT_INVENTORY_ENTRY)
    }
}

impl core::ops::BitOr for EmbedFlags {
    type Output = Self;

    fn bitor(self, rhs: Self) -> Self::Output {
        self.union(rhs)
    }
}

impl core::ops::BitOrAssign for EmbedFlags {
    fn bitor_assign(&mut self, rhs: Self) {
        self.insert(rhs);
    }
}

impl core::ops::BitAnd for EmbedFlags {
    type Output = Self;

    fn bitand(self, rhs: Self) -> Self::Output {
        self.intersection(rhs)
    }
}

impl core::ops::BitAndAssign for EmbedFlags {
    fn bitand_assign(&mut self, rhs: Self) {
        self.0 &= rhs.0;
    }
}

impl core::ops::BitXor for EmbedFlags {
    type Output = Self;

    fn bitxor(self, rhs: Self) -> Self::Output {
        self.symmetric_difference(rhs)
    }
}

impl core::ops::BitXorAssign for EmbedFlags {
    fn bitxor_assign(&mut self, rhs: Self) {
        self.toggle(rhs);
    }
}

impl core::ops::Not for EmbedFlags {
    type Output = Self;

    fn not(self) -> Self::Output {
        self.complement()
    }
}

impl From<u64> for EmbedFlags {
    fn from(bits: u64) -> Self {
        Self::from_bits(bits)
    }
}

impl From<EmbedFlags> for u64 {
    fn from(flags: EmbedFlags) -> Self {
        flags.bits()
    }
}

#[cfg(test)]
mod tests {
    use super::{EmbedFlags, EmbedType};

    #[test]
    fn embed_type_names() {
        let values = [
            (EmbedType::Rich, "rich"),
            (EmbedType::Image, "image"),
            (EmbedType::Video, "video"),
            (EmbedType::Gifv, "gifv"),
            (EmbedType::Article, "article"),
            (EmbedType::Link, "link"),
        ];

        for (kind, name) in values {
            assert_eq!(kind.as_str(), name);
            assert_eq!(kind.to_string(), name);
            assert_eq!(EmbedType::from_name(name), Some(kind));
        }

        assert_eq!(EmbedType::from_name("unknown"), None);
        assert_eq!(EmbedType::default(), EmbedType::Rich);
    }

    #[test]
    fn embed_flag_values_and_operators() {
        assert_eq!(EmbedFlags::CONTAINS_EXPLICIT_MEDIA.bits(), 1 << 4);
        assert_eq!(EmbedFlags::CONTENT_INVENTORY_ENTRY.bits(), 1 << 5);
        assert_eq!(!EmbedFlags::none(), EmbedFlags::all());

        let flags = EmbedFlags::CONTAINS_EXPLICIT_MEDIA | EmbedFlags::CONTENT_INVENTORY_ENTRY;
        assert!(flags.contains_explicit_media());
        assert!(flags.content_inventory_entry());
        assert!(flags.contains(EmbedFlags::CONTAINS_EXPLICIT_MEDIA));

        let mut mutable = EmbedFlags::none();
        mutable.insert(EmbedFlags::CONTAINS_EXPLICIT_MEDIA);
        assert!(mutable.contains_explicit_media());
        mutable.remove(EmbedFlags::CONTAINS_EXPLICIT_MEDIA);
        assert!(!mutable.contains_explicit_media());

        assert_eq!(u64::from(flags), flags.bits());
        assert_eq!(EmbedFlags::from(flags.bits()), flags);
    }
}
